  let idx=0;
  function expectStr(){
    const tk=tokens[idx];
    if(!tk||tk.t!=='str') throw new Error(`Expected string at token ${idx}`);
    idx++; return tk.v;
  }
  function parseObject(){
    const obj={};
    while(idx<tokens.length){
      const tk=tokens[idx];
      if(tk.t==='}') {idx++; break;}
      const key=expectStr();
      const next=tokens[idx];
      if(!next) throw new Error(`Unexpected EOF after key: ${key}`);
      if(next.t==='{') {idx++; obj[key]=parseObject();}
      else if(next.t==='str'){ const val=expectStr(); obj[key]=val; }
      else throw new Error(`Unexpected token after key ${key} at ${idx}`);
    }
